import{_ as a,o as s,c as t,a0 as i}from"./chunks/framework.tVbs9ddD.js";const m=JSON.parse('{"title":"How-to: summarizers","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/llm-summarizer.md","filePath":"how-to/llm-summarizer.md"}'),o={name:"how-to/llm-summarizer.md"};function n(d,e,r,c,l,p){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="how-to-summarizers" tabindex="-1">How-to: summarizers <a class="header-anchor" href="#how-to-summarizers" aria-label="Permalink to &quot;How-to: summarizers&quot;">​</a></h1><p><code>kuda-cards</code> turns extractions into the committed YAML artifacts. Two shipping adapters: <code>template</code> (deterministic) and <code>acp</code> (agent-written prose); <code>llm</code> is parked — ACP is the semantic path.</p><h2 id="acp-—-agent-written-cards" tabindex="-1"><code>acp</code> — agent-written cards <a class="header-anchor" href="#acp-—-agent-written-cards" aria-label="Permalink to &quot;`acp` — agent-written cards&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">summarize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">acp_cmd = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;env CLINE_PROVIDER=cline-pass CLINE_MODEL=cline-free/mimo-v2.6-flash cline --acp&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># NOTE: provider/model are env vars, not CLI flags — -P/-m are</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ignored in ACP mode.</span></span></code></pre></div><p><code>sync</code> spawns the agent once per run (one session, reused across modules) and sends each module a session/prompt asking for <code>purpose:</code>/<code>invariants:</code>/<code>notes:</code> grounded in the file list. The agent&#39;s prose fills the card&#39;s <code>purpose</code> + <code>notes</code> regions — <code>api</code>/<code>deps</code>/<code>verify</code>/<code>provenance</code> stay mechanical.</p><p>Protocol notes:</p><ul><li>session/request_permission from the agent is auto-answered with the first option — required, or the prompt deadlocks</li><li>Any ACP-capable agent works: <code>cline --acp</code>, <code>zed agent</code>, <code>gemini --experimental-acp</code>, …</li><li>Auth lives in the agent — kuda holds no keys</li><li>Agent failure → silent <code>template</code> fallback per module</li></ul><h2 id="template-default-shipping" tabindex="-1"><code>template</code> (default, shipping) <a class="header-anchor" href="#template-default-shipping" aria-label="Permalink to &quot;`template` (default, shipping)&quot;">​</a></h2><p>Deterministic, zero-model. Each module card&#39;s <code>purpose</code> comes from the manifest <code>description</code> field (Cargo.toml <code>[package].description</code>, package.json <code>description</code>); <code>api</code> lists the extracted public symbols; <code>deps</code> lists the module&#39;s edges; <code>verify:</code> lists the files the card was built from.</p><p>Because it is mechanical, <code>template</code> output is stable — the same inputs always produce the same card, so diffs mean real change. That is the property you want in committed, reviewed artifacts.</p><h2 id="llm-parked" tabindex="-1"><code>llm</code> (parked) <a class="header-anchor" href="#llm-parked" aria-label="Permalink to &quot;`llm` (parked)&quot;">​</a></h2><p>A direct-provider adapter (<code>provider</code>/<code>model</code> + keyring) is in the backlog — ACP is preferred because it is agent-agnostic and key-free. Same grounding rules apply when it lands: cite files or stay silent, never clobber <code>verify:</code> or human <code>notes:</code>.</p><h2 id="incremental-sync" tabindex="-1">Incremental sync <a class="header-anchor" href="#incremental-sync" aria-label="Permalink to &quot;Incremental sync&quot;">​</a></h2><p><code>sync</code> compares each module&#39;s input-file hashes with the committed card&#39;s <code>provenance.hashes</code> before calling the summarizer — identical means the card is reused and the agent is never prompted. Change one file and only that module re-summarizes; the agent spend is per-drift, not per-sync.</p>',14)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
